const (
	testJWTSecret      = "test-secret-with-enough-bytes-for-jwt"
	otherTestJWTSecret = "other-secret-with-enough-bytes-for-jwt"
	testJWTLifetime    = 24 * time.Hour
)

// Generated by Codex and not thoroughly checked for correctness.
func TestGenerateAndVerifyToken(t *testing.T) {
	utils.Init(testJWTSecret, testJWTLifetime, []string{"current"}, map[string]string{"current": testJWTSecret})

	const (
		email  = "user@example.com"
		userID = int64(42)
	)
	issuedBefore := time.Now()
	token, err := utils.GenerateToken(email, userID)
	issuedAfter := time.Now()
	if err != nil {
		t.Fatalf("GenerateToken() error = %v", err)
	}

	gotUserID, err := utils.VerifyToken(token)
	if err != nil {
		t.Fatalf("VerifyToken() error = %v", err)
	}
	if gotUserID != userID {
		t.Fatalf("VerifyToken() userID = %d, want %d", gotUserID, userID)
	}

	claims := jwt.MapClaims{}
	parsedToken, err := jwt.ParseWithClaims(token, claims, func(token *jwt.Token) (interface{}, error) {
		return []byte(testJWTSecret), nil
	})
	if err != nil {
		t.Fatalf("ParseWithClaims() error = %v", err)
	}
	if parsedToken.Method != jwt.SigningMethodHS256 {
		t.Fatalf("token method = %v, want %v", parsedToken.Method, jwt.SigningMethodHS256)
	}
	if claims["email"] != email {
		t.Fatalf("email claim = %v, want %s", claims["email"], email)
	}
	if claims["userId"] != float64(userID) {
		t.Fatalf("userId claim = %v, want %d", claims["userId"], userID)
	}

	exp, ok := claims["exp"].(float64)
	if !ok {
		t.Fatalf("exp claim type = %T, want float64", claims["exp"])
	}
	expiresAt := time.Unix(int64(exp), 0)
	minExpectedExpiry := time.Unix(issuedBefore.Add(testJWTLifetime).Unix(), 0)
	maxExpectedExpiry := time.Unix(issuedAfter.Add(testJWTLifetime).Unix(), 0)
	if expiresAt.Before(minExpectedExpiry) || expiresAt.After(maxExpectedExpiry) {
		t.Fatalf("exp claim = %s, want configured lifetime %s after issuance between %s and %s", expiresAt, testJWTLifetime, minExpectedExpiry, maxExpectedExpiry)
	}
}

