// Generated by Codex and not thoroughly checked for correctness.
func TestVerifyTokenRejectsInvalidUserIDClaims(t *testing.T) {
	utils.Init(testJWTSecret, testJWTLifetime, []string{"current"}, map[string]string{"current": testJWTSecret})

	testCases := []struct {
		name   string
		claims jwt.MapClaims
	}{
		{
			name: "missing userId claim is rejected",
			claims: jwt.MapClaims{
				"exp": time.Now().Add(time.Hour).Unix(),
			},
		},
		{
			name: "string userId claim is rejected",
			claims: jwt.MapClaims{
				"userId": "42",
				"exp":    time.Now().Add(time.Hour).Unix(),
			},
		},
		{
			name: "boolean userId claim is rejected",
			claims: jwt.MapClaims{
				"userId": true,
				"exp":    time.Now().Add(time.Hour).Unix(),
			},
		},
		{
			name: "null userId claim is rejected",
			claims: jwt.MapClaims{
				"userId": nil,
				"exp":    time.Now().Add(time.Hour).Unix(),
			},
		},
		{
			name: "fractional userId claim is rejected",
			claims: jwt.MapClaims{
				"userId": 42.5,
				"exp":    time.Now().Add(time.Hour).Unix(),
			},
		},
	}

	for _, testCase := range testCases {
		t.Run(testCase.name, func(t *testing.T) {
			token := signTestToken(t, testJWTSecret, jwt.SigningMethodHS256, testCase.claims)

			_, err := utils.VerifyToken(token)
			if err == nil {
				t.Fatal("VerifyToken() error = nil, want invalid userId claim error")
			}
			if !strings.Contains(err.Error(), "invalid userId claim") {
				t.Fatalf("VerifyToken() error = %v, want invalid userId claim", err)
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestJWTKeyRotationPreservesSessionsUntilKeyRemoval(t *testing.T) {
	utils.Init(testJWTSecret, testJWTLifetime, []string{"old"}, map[string]string{"old": testJWTSecret})
	oldToken, err := utils.GenerateToken("user@example.com", 42)
	if err != nil {
		t.Fatal(err)
	}
	legacyToken := signTestToken(t, testJWTSecret, jwt.SigningMethodHS256, jwt.MapClaims{
		"userId": 42, "exp": time.Now().Add(time.Hour).Unix(),
	})
	keys := map[string]string{"old": testJWTSecret, "new": otherTestJWTSecret}
	activeIDs := []string{"new"}
	utils.Init(testJWTSecret, testJWTLifetime, activeIDs, keys)
	// Changing the caller's map must not change installed signing configuration.
	delete(keys, "old")
	keys["new"] = "changed-after-initialization"
	activeIDs[0] = "old"
	newToken, err := utils.GenerateToken("user@example.com", 42)
	if err != nil {
		t.Fatal(err)
	}
	parsed, err := jwt.Parse(newToken, func(token *jwt.Token) (any, error) {
		return []byte(otherTestJWTSecret), nil
	})
	if err != nil || parsed.Header["kid"] != "new" {
		t.Fatalf("new token did not use the active key: token=%v error=%v", parsed, err)
	}
	for name, token := range map[string]string{"old": oldToken, "new": newToken, "legacy": legacyToken} {
		userID, err := utils.VerifyToken(token)
		if err != nil || userID != 42 {
			t.Fatalf("retained %s token: userID=%d error=%v", name, userID, err)
		}
	}
	utils.Init("", testJWTLifetime, []string{"new"}, map[string]string{"new": otherTestJWTSecret})
	for name, token := range map[string]string{"old": oldToken, "legacy": legacyToken} {
		if _, err := utils.VerifyToken(token); err == nil {
			t.Fatalf("removed %s key still verifies tokens", name)
		}
	}
	if userID, err := utils.VerifyToken(newToken); err != nil || userID != 42 {
		t.Fatalf("active token after removal: userID=%d error=%v", userID, err)
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestJWTKeySelectionRejectsInvalidTokens(t *testing.T) {
	for _, testCase := range []struct {
		name       string
		keyID      any
		secret     string
		expiration time.Time
	}{
		{name: "unknown ID cannot fall back to legacy key", keyID: "unknown", secret: testJWTSecret},
		{name: "empty ID cannot fall back to legacy key", keyID: "", secret: testJWTSecret},
		{name: "numeric ID is rejected", keyID: 42, secret: testJWTSecret},
		{name: "null ID is rejected", secret: testJWTSecret},
		{name: "signature must match selected key", keyID: "new", secret: testJWTSecret},
		{name: "retained key cannot bypass expiration", keyID: "old", secret: testJWTSecret, expiration: time.Now().Add(-time.Hour)},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			utils.Init(testJWTSecret, testJWTLifetime, []string{"new"}, map[string]string{
				"old": testJWTSecret, "new": otherTestJWTSecret,
			})
			expiration := testCase.expiration
			if expiration.IsZero() {
				expiration = time.Now().Add(time.Hour)
			}
			token := jwt.NewWithClaims(jwt.SigningMethodHS256, jwt.MapClaims{"userId": 42, "exp": expiration.Unix()})
			token.Header["kid"] = testCase.keyID
			signed, err := token.SignedString([]byte(testCase.secret))
			if err != nil {
				t.Fatal(err)
			}
			if _, err := utils.VerifyToken(signed); err == nil {
				t.Fatal("invalid token was accepted")
			}
		})
	}
}

