// Generated by Codex and not thoroughly checked for correctness.
func TestGenerateTokenRejectsInvalidSigningConfiguration(t *testing.T) {
	for _, testCase := range []struct {
		name      string
		activeIDs []string
		wantError string
		wantCause error
	}{
		{name: "no active keys", wantError: "no active signing keys"},
		{name: "missing active key", activeIDs: []string{"missing"}, wantError: "active signing key is not configured"},
		{name: "random source failure", activeIDs: []string{"first", "second"}, wantError: "select signing key", wantCause: io.EOF},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			originalReader := rand.Reader
			rand.Reader = bytes.NewReader(nil)
			t.Cleanup(func() { rand.Reader = originalReader })
			utils.Init("", testJWTLifetime, testCase.activeIDs, nil)
			token, err := utils.GenerateToken("user@example.com", 42)
			if err == nil || !strings.Contains(err.Error(), testCase.wantError) || token != "" {
				t.Fatalf("invalid signing configuration: token=%q error=%v", token, err)
			}
			if testCase.wantCause != nil && !errors.Is(err, testCase.wantCause) {
				t.Fatalf("error = %v, want cause %v", err, testCase.wantCause)
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestGenerateTokenUsesEachActiveKeyAndExcludesRetainedKeys(t *testing.T) {
	const secondActiveSecret = "second-active-secret-with-at-least-32-bytes"
	keys := map[string]string{"old": testJWTSecret, "first": otherTestJWTSecret, "second": secondActiveSecret}
	for _, testCase := range []struct {
		keyID      string
		randomByte byte
	}{
		{keyID: "first", randomByte: 0},
		{keyID: "second", randomByte: 1},
	} {
		t.Run(testCase.keyID, func(t *testing.T) {
			// Control only entropy so the real selection and signing paths run.
			originalReader := rand.Reader
			rand.Reader = bytes.NewReader([]byte{testCase.randomByte})
			t.Cleanup(func() { rand.Reader = originalReader })
			utils.Init("", testJWTLifetime, []string{"first", "second"}, keys)
			token, err := utils.GenerateToken("user@example.com", 42)
			if err != nil {
				t.Fatal(err)
			}
			parsed, err := jwt.Parse(token, func(token *jwt.Token) (any, error) {
				return []byte(keys[testCase.keyID]), nil
			})
			if err != nil || parsed.Header["kid"] != testCase.keyID {
				t.Fatalf("token did not use expected active key %s: error=%v", testCase.keyID, err)
			}
			if userID, err := utils.VerifyToken(token); err != nil || userID != 42 {
				t.Fatalf("active token failed verification: userID=%d error=%v", userID, err)
			}
		})
	}
}

func signTestToken(t *testing.T, secret string, method jwt.SigningMethod, claims jwt.MapClaims) string {
	t.Helper()

	token, err := jwt.NewWithClaims(method, claims).SignedString([]byte(secret))
	if err != nil {
		t.Fatalf("SignedString() error = %v", err)
	}
	return token
}
